SELECT jsonb_build_object('read13_marker','ConsentDisposition/root'::text,'position','BEFORE'::text);
SELECT jsonb_build_object('model','ConsentPresentation','ids',coalesce(jsonb_agg(observed.id::text ORDER BY observed.id::text COLLATE "C"),'[]'::jsonb)) FROM (SELECT id,user_id,content_revision_id,rendered_text,rendered_hash,render_version,context_owner,context_kind,context_id,action_owner,action,created_at,mutation_transaction_id FROM app.consent_presentation WHERE id IN ('128c8a77-f59a-5a02-bc2b-92237ac491c4'::uuid)) observed;
SELECT jsonb_build_object('model','ConsentDisposition','ids',coalesce(jsonb_agg(observed.id::text ORDER BY observed.id::text COLLATE "C"),'[]'::jsonb)) FROM (SELECT id,proof_id,user_id,presentation_id,kind,semantic_key,fingerprint,created_at,mutation_transaction_id FROM app.consent_disposition WHERE id IN ('0d227778-2dcc-5dbb-b7d6-a10509ed527f'::uuid,'f9f011da-46bf-5e7e-98a7-da1c034295a8'::uuid)) observed;
SET CONSTRAINTS ALL IMMEDIATE;
SELECT jsonb_build_object('read13_marker','ConsentDisposition/root'::text,'position','AFTER'::text);
